const SI={};SN.forEach((s,i)=>SI[s]=i);
function sidx(s){if(s[0]==="'")s=s.slice(1,-1).replace(/''/g,"'");const i=SI[s];if(i===undefined)throw new Error('Unknown sheet '+s);return i}
function pa(ref){const i=ref.lastIndexOf('!');return[sidx(ref.slice(0,i)),ref.slice(i+1).replace(/\$/g,'').toUpperCase()]}
function createModel(ov){let memo,o={};const clr=()=>{memo=FX.map(()=>new Map())};clr();
const safe=f=>{try{return f()}catch(e){if(e instanceof RangeError){M.warm();return f()}throw e}};
const M={
c(si,a){const m=memo[si];if(m.has(a))return m.get(a);const k=si+'|'+a;let v;
if(k in o)v=o[k];else{const f=FX[si][a];if(f){m.set(a,0);try{v=f(M)}catch(e){m.delete(a);if(e instanceof RangeError)throw e;v=VE}
if(v instanceof Rg)v=sc(v);if(v===null||v===undefined)v=0}else{v=IN[si][a];if(v===undefined)v=null}}
m.set(a,v);return v},
r(si,r1,c1,r2,c2){const z=[];for(let i=r1;i<=r2;i++){const w=[];for(let j=c1;j<=c2;j++)w.push(M.c(si,CL(j)+i));z.push(w)}return new Rg(z)},
get(ref){const[si,a]=pa(ref);return safe(()=>M.c(si,a))},
set(ref,v){const[si,a]=pa(ref);o[si+'|'+a]=v;clr()},
reset(){o={};clr()},
range(s,r){const si=sidx(s),p=r.replace(/\$/g,'').toUpperCase().split(':'),x=dc(p[0]),y=dc(p[1]||p[0]);
return safe(()=>M.r(si,Math.min(x[0],y[0]),Math.min(x[1],y[1]),Math.max(x[0],y[0]),Math.max(x[1],y[1])).a)},
warm(){for(let p=0;p<10000;p++){let bad=false;for(let si=0;si<FX.length;si++)for(const a in FX[si]){if(memo[si].has(a))continue;try{M.c(si,a)}catch(e){if(e instanceof RangeError)bad=true;else throw e}}if(!bad)return}}
};
if(ov)for(const k in ov)M.set(k,ov[k]);return M}
const inputs={},formulas={};SN.forEach((s,i)=>{for(const a in IN[i])inputs[s+'!'+a]=IN[i][a];for(const a in FS[i])formulas[s+'!'+a]=FS[i][a]});
const G={inputs,formulas,createModel,XLError,E,sheets:SN};
